    int totalSubstrings = 1 << k; // This is 2^k, the number of all possible binary strings of length k
    boolean[] found = new boolean[totalSubstrings];
    int allOnes = totalSubstrings - 1; // This is 2^k - 1, all bits set to 1
    int hashVal = 0;

    for (int i = 0; i < s.length(); i++) {
        // Calculate hash value for the substring of length k ending at i
        hashVal = ((hashVal << 1) & allOnes) | (s.charAt(i) - '0');

        // Only consider valid substrings of length k
